def find_closest_elements(numbers: List[float]) -> Tuple[float, float]:
    numbers.sort()
    closest_pair = (numbers[0], numbers[1])
    for i in range(2, len(numbers)):
        if numbers[i] - closest_pair[0] < closest_pair[1] - closest_pair[0]:
            closest_pair = (closest_pair[0], numbers[i])
        elif numbers[i] - closest_pair[0] == closest_pair[1] - closest_pair[0]:
            closest_pair = (numbers[i-1], numbers[i])
    return closest_pair

