        return abs(a-b) <= max(rel_tol * max(abs(a), abs(b)), abs_tol)

    def rational_root_theorem(xs):
        factors = []
        for i in range(1, abs(xs[-1]) + 1):
            if xs[-1] % i == 0:
                factors.append(i)
                factors.append(-i)
        return factors

    def synthetic_division(xs, root):
        quotient = [xs[0]]
        for i in range(1, len(xs)):
            quotient.append(quotient[-1] * root + xs[i])
        return quotient

    factors = rational_root_theorem(xs)
    for factor in factors:
        if isclose(poly(xs, factor), 0):
            return factor
        quotient = synthetic_division(xs, factor)
        if isclose(poly(quotient, 0), 0):
            return 0
    return None

