def encrypt(s):
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    shifted_alphabet = alphabet[4:] + alphabet[:4]
    mapping = str.maketrans(alphabet, shifted_alphabet)
    return s.translate(mapping)

def encrypt(s):
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    encrypted_alphabet = alphabet[4:] + alphabet[:4]
    encrypted_s = ''
    for char in s:
        if char.isalpha():
            if char.islower():
                encrypted_s += encrypted_alphabet[alphabet.index(char)]
            else:
                encrypted_s += encrypted_alphabet[alphabet.index(char.lower())].upper()
        else:
            encrypted_s += char
    return encrypted_s

